import React, { useState, useEffect } from 'react';
import { 
  Container, 
  Typography, 
  Grid, 
  Card, 
  CardContent, 
  Button, 
  Box,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Alert,
  Snackbar,
  Tab,
  Tabs
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

const InstitutionDashboard = () => {
  const [applications, setApplications] = useState([]);
  const [faculties, setFaculties] = useState([]);
  const [courses, setCourses] = useState([]);
  const [stats, setStats] = useState({ 
    totalApplications: 0, 
    pending: 0, 
    admitted: 0,
    totalFaculties: 0,
    totalCourses: 0
  });
  const [openFacultyDialog, setOpenFacultyDialog] = useState(false);
  const [openCourseDialog, setOpenCourseDialog] = useState(false);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [activeTab, setActiveTab] = useState(0);
  const [newFaculty, setNewFaculty] = useState({ name: '', description: '' });
  const [newCourse, setNewCourse] = useState({ 
    name: '', 
    description: '', 
    facultyId: '',
    requirements: '',
    duration: '',
    fees: '',
    seats: ''
  });

  const { currentUser } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [applicationsRes, institutionRes] = await Promise.all([
        axios.get('http://localhost:5000/api/applications/institution'),
        axios.get(`http://localhost:5000/api/institutions/${currentUser.userId}`)
      ]);

      const apps = applicationsRes.data.applications;
      setApplications(apps.slice(0, 5));
      
      const pending = apps.filter(app => app.status === 'pending').length;
      const admitted = apps.filter(app => app.status === 'admitted').length;

      if (institutionRes.data.faculties && institutionRes.data.courses) {
        setFaculties(institutionRes.data.faculties);
        setCourses(institutionRes.data.courses);
      }

      setStats({
        totalApplications: apps.length,
        pending,
        admitted,
        totalFaculties: institutionRes.data.faculties?.length || 0,
        totalCourses: institutionRes.data.courses?.length || 0
      });
    } catch (error) {
      console.error('Error fetching data:', error);
      showSnackbar('Error loading data', 'error');
    }
  };

  const showSnackbar = (message, severity = 'success') => {
    setSnackbar({ open: true, message, severity });
  };

  const handleAddFaculty = async () => {
    try {
      await axios.post(`http://localhost:5000/api/institutions/${currentUser.userId}/faculties`, newFaculty);
      setOpenFacultyDialog(false);
      setNewFaculty({ name: '', description: '' });
      showSnackbar('Faculty added successfully');
      fetchData();
    } catch (error) {
      showSnackbar('Error adding faculty', 'error');
    }
  };

  const handleAddCourse = async () => {
    try {
      await axios.post(`http://localhost:5000/api/institutions/${currentUser.userId}/courses`, {
        ...newCourse,
        fees: parseInt(newCourse.fees),
        seats: parseInt(newCourse.seats),
        requirements: newCourse.requirements.split(',').map(req => req.trim())
      });
      setOpenCourseDialog(false);
      setNewCourse({ 
        name: '', description: '', facultyId: '', requirements: '', duration: '', fees: '', seats: '' 
      });
      showSnackbar('Course added successfully');
      fetchData();
    } catch (error) {
      showSnackbar('Error adding course', 'error');
    }
  };

  const handleAdmitStudent = async (applicationId, studentId) => {
    try {
      // First check if student is already admitted to any course in this institution
      const studentApplications = applications.filter(app => 
        app.studentId === studentId && app.status === 'admitted'
      );

      if (studentApplications.length > 0) {
        showSnackbar('This student is already admitted to a program in your institution', 'error');
        return;
      }

      await axios.put(`http://localhost:5000/api/applications/${applicationId}/status`, {
        status: 'admitted'
      });
      showSnackbar('Student admitted successfully');
      fetchData();
    } catch (error) {
      showSnackbar('Error admitting student', 'error');
    }
  };

  const handleRejectStudent = async (applicationId) => {
    try {
      await axios.put(`http://localhost:5000/api/applications/${applicationId}/status`, {
        status: 'rejected'
      });
      showSnackbar('Application rejected');
      fetchData();
    } catch (error) {
      showSnackbar('Error rejecting application', 'error');
    }
  };

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Institution Dashboard
      </Typography>

      {/* Stats Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} md={2.4}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Total Applications
              </Typography>
              <Typography variant="h4">
                {stats.totalApplications}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={2.4}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Pending
              </Typography>
              <Typography variant="h4" color="orange">
                {stats.pending}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={2.4}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Admitted
              </Typography>
              <Typography variant="h4" color="green">
                {stats.admitted}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={2.4}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Faculties
              </Typography>
              <Typography variant="h4">
                {stats.totalFaculties}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={2.4}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Courses
              </Typography>
              <Typography variant="h4">
                {stats.totalCourses}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Quick Actions */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} md={4}>
          <Card sx={{ cursor: 'pointer' }} onClick={() => navigate('/applications')}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                📋 Manage Applications
              </Typography>
              <Typography color="textSecondary">
                Review and process student applications
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={4}>
          <Card sx={{ cursor: 'pointer' }} onClick={() => setOpenFacultyDialog(true)}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                🏛️ Add Faculty
              </Typography>
              <Typography color="textSecondary">
                Create new faculties for your institution
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={4}>
          <Card sx={{ cursor: 'pointer' }} onClick={() => setOpenCourseDialog(true)}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                📚 Add Course
              </Typography>
              <Typography color="textSecondary">
                Create new courses under faculties
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Tabs for different sections */}
      <Paper sx={{ width: '100%', mb: 2 }}>
        <Tabs value={activeTab} onChange={handleTabChange} aria-label="institution tabs">
          <Tab label="Recent Applications" />
          <Tab label="Faculties" />
          <Tab label="Courses" />
        </Tabs>
      </Paper>

      {/* Applications Tab */}
      {activeTab === 0 && applications.length > 0 && (
        <Paper sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>
            Recent Applications
          </Typography>
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Student</TableCell>
                  <TableCell>Course</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Applied Date</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {applications.map((app) => (
                  <TableRow key={app.id}>
                    <TableCell>
                      {app.student?.personalInfo?.firstName} {app.student?.personalInfo?.lastName}
                      <br />
                      <Typography variant="body2" color="textSecondary">
                        {app.student?.personalInfo?.email}
                      </Typography>
                    </TableCell>
                    <TableCell>{app.course?.name}</TableCell>
                    <TableCell>
                      <Chip 
                        label={app.status} 
                        color={
                          app.status === 'admitted' ? 'success' :
                          app.status === 'rejected' ? 'error' : 'warning'
                        }
                        size="small"
                      />
                    </TableCell>
                    <TableCell>
                      {new Date(app.appliedAt).toLocaleDateString()}
                    </TableCell>
                    <TableCell>
                      {app.status === 'pending' && (
                        <Box sx={{ display: 'flex', gap: 1 }}>
                          <Button
                            size="small"
                            variant="contained"
                            color="success"
                            onClick={() => handleAdmitStudent(app.id, app.studentId)}
                          >
                            Admit
                          </Button>
                          <Button
                            size="small"
                            variant="outlined"
                            color="error"
                            onClick={() => handleRejectStudent(app.id)}
                          >
                            Reject
                          </Button>
                        </Box>
                      )}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      )}

      {/* Faculties Tab */}
      {activeTab === 1 && (
        <Paper sx={{ p: 2 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
            <Typography variant="h6">
              Faculties ({faculties.length})
            </Typography>
            <Button variant="contained" onClick={() => setOpenFacultyDialog(true)}>
              Add Faculty
            </Button>
          </Box>
          <Grid container spacing={2}>
            {faculties.map((faculty) => (
              <Grid item xs={12} md={6} key={faculty.id}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      {faculty.name}
                    </Typography>
                    <Typography color="textSecondary">
                      {faculty.description || 'No description'}
                    </Typography>
                    <Typography variant="body2" sx={{ mt: 1, color: 'primary.main' }}>
                      {courses.filter(course => course.facultyId === faculty.id).length} courses
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Paper>
      )}

      {/* Courses Tab */}
      {activeTab === 2 && (
        <Paper sx={{ p: 2 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
            <Typography variant="h6">
              Courses ({courses.length})
            </Typography>
            <Button variant="contained" onClick={() => setOpenCourseDialog(true)}>
              Add Course
            </Button>
          </Box>
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Course Name</TableCell>
                  <TableCell>Faculty</TableCell>
                  <TableCell>Duration</TableCell>
                  <TableCell>Fees</TableCell>
                  <TableCell>Seats</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {courses.map((course) => (
                  <TableRow key={course.id}>
                    <TableCell>
                      <Typography variant="subtitle1">{course.name}</Typography>
                      <Typography variant="body2" color="textSecondary">
                        {course.description}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      {faculties.find(f => f.id === course.facultyId)?.name || 'N/A'}
                    </TableCell>
                    <TableCell>{course.duration}</TableCell>
                    <TableCell>M{course.fees}</TableCell>
                    <TableCell>{course.seats}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      )}

      {/* Add Faculty Dialog */}
      <Dialog open={openFacultyDialog} onClose={() => setOpenFacultyDialog(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Add New Faculty</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="Faculty Name"
            fullWidth
            variant="outlined"
            value={newFaculty.name}
            onChange={(e) => setNewFaculty({...newFaculty, name: e.target.value})}
            sx={{ mb: 2 }}
          />
          <TextField
            margin="dense"
            label="Description"
            fullWidth
            variant="outlined"
            multiline
            rows={3}
            value={newFaculty.description}
            onChange={(e) => setNewFaculty({...newFaculty, description: e.target.value})}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenFacultyDialog(false)}>Cancel</Button>
          <Button onClick={handleAddFaculty} variant="contained">Add Faculty</Button>
        </DialogActions>
      </Dialog>

      {/* Add Course Dialog */}
      <Dialog open={openCourseDialog} onClose={() => setOpenCourseDialog(false)} maxWidth="md" fullWidth>
        <DialogTitle>Add New Course</DialogTitle>
        <DialogContent>
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField
                label="Course Name"
                fullWidth
                value={newCourse.name}
                onChange={(e) => setNewCourse({...newCourse, name: e.target.value})}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                label="Description"
                fullWidth
                multiline
                rows={2}
                value={newCourse.description}
                onChange={(e) => setNewCourse({...newCourse, description: e.target.value})}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                select
                label="Faculty"
                fullWidth
                value={newCourse.facultyId}
                onChange={(e) => setNewCourse({...newCourse, facultyId: e.target.value})}
                SelectProps={{ native: true }}
              >
                <option value="">Select Faculty</option>
                {faculties.map((faculty) => (
                  <option key={faculty.id} value={faculty.id}>
                    {faculty.name}
                  </option>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                label="Duration"
                fullWidth
                value={newCourse.duration}
                onChange={(e) => setNewCourse({...newCourse, duration: e.target.value})}
                placeholder="e.g., 4 years"
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                label="Fees (M)"
                type="number"
                fullWidth
                value={newCourse.fees}
                onChange={(e) => setNewCourse({...newCourse, fees: e.target.value})}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                label="Available Seats"
                type="number"
                fullWidth
                value={newCourse.seats}
                onChange={(e) => setNewCourse({...newCourse, seats: e.target.value})}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                label="Requirements (comma separated)"
                fullWidth
                value={newCourse.requirements}
                onChange={(e) => setNewCourse({...newCourse, requirements: e.target.value})}
                placeholder="e.g., High School Diploma, Mathematics, English"
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenCourseDialog(false)}>Cancel</Button>
          <Button onClick={handleAddCourse} variant="contained">Add Course</Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={4000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
      >
        <Alert severity={snackbar.severity} onClose={() => setSnackbar({ ...snackbar, open: false })}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default InstitutionDashboard;
